import { existsSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const manifestPath = join(repoRoot, "src-tauri", "Cargo.toml");
const appGradlePath = join(
  repoRoot,
  "src-tauri",
  "gen",
  "android",
  "app",
  "tauri.build.gradle.kts",
);
const outputPath = join(
  repoRoot,
  "src-tauri",
  "gen",
  "android",
  "tauri.settings.gradle",
);

const metadataResult = spawnSync(
  "cargo",
  [
    "metadata",
    "--locked",
    "--manifest-path",
    manifestPath,
    "--format-version",
    "1",
  ],
  {
    cwd: repoRoot,
    encoding: "utf8",
    maxBuffer: 32 * 1024 * 1024,
  },
);

if (metadataResult.error) {
  throw metadataResult.error;
}
if (metadataResult.status !== 0) {
  throw new Error(
    `cargo metadata failed with exit code ${metadataResult.status}: ${metadataResult.stderr.trim()}`,
  );
}

const metadata = JSON.parse(metadataResult.stdout);
const rootId = metadata.resolve?.root;
const rootNode = metadata.resolve?.nodes?.find((node) => node.id === rootId);
if (!rootId || !rootNode) {
  throw new Error("cargo metadata did not identify the application package");
}

const packageById = new Map(metadata.packages.map((pkg) => [pkg.id, pkg]));
const modulesByName = new Map();
for (const dependency of rootNode.deps) {
  const isRuntimeDependency = dependency.dep_kinds.some(
    ({ kind }) => kind === null,
  );
  if (!isRuntimeDependency) {
    continue;
  }

  const pkg = packageById.get(dependency.pkg);
  if (!pkg) {
    throw new Error(`cargo metadata is missing package ${dependency.pkg}`);
  }
  if (pkg.name !== "tauri" && !pkg.name.startsWith("tauri-plugin-")) {
    continue;
  }

  const packageRoot = dirname(pkg.manifest_path);
  const androidDirectory =
    pkg.name === "tauri"
      ? join(packageRoot, "mobile", "android")
      : join(packageRoot, "android");
  if (
    !existsSync(androidDirectory) ||
    !statSync(androidDirectory).isDirectory()
  ) {
    if (pkg.name === "tauri") {
      throw new Error("Android library directory is missing for tauri-android");
    }
    continue;
  }

  const moduleName = pkg.name === "tauri" ? "tauri-android" : pkg.name;
  if (modulesByName.has(moduleName)) {
    throw new Error(`duplicate Android project dependency: ${moduleName}`);
  }
  modulesByName.set(moduleName, androidDirectory);
}

if (!modulesByName.has("tauri-android")) {
  throw new Error("cargo metadata has no direct runtime dependency on tauri");
}

const requiredModules = Array.from(modulesByName, ([name, directory]) => ({
  name,
  directory,
})).sort((left, right) => {
  if (left.name === "tauri-android") return -1;
  if (right.name === "tauri-android") return 1;
  return left.name < right.name ? -1 : left.name > right.name ? 1 : 0;
});

const appGradleLines = [
  "// THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.",
  "val implementation by configurations",
  "dependencies {",
  '  implementation("androidx.lifecycle:lifecycle-process:2.10.0")',
  ...requiredModules.map(
    ({ name }) => `  implementation(project(\":${name}\"))`,
  ),
  "}",
];
writeFileSync(appGradlePath, `${appGradleLines.join("\n")}\n`, "utf8");

const quoteGroovy = (value) =>
  `'${value.replaceAll("\\", "\\\\").replaceAll("'", "\\'")}'`;
const lines = [
  "// THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.",
];
for (const { name, directory } of requiredModules) {
  lines.push(`include ':${name}'`);
  lines.push(
    `project(':${name}').projectDir = new File(${quoteGroovy(directory)})`,
  );
}

writeFileSync(outputPath, `${lines.join("\n")}\n`, "utf8");
console.log(
  `Generated Android build files for ${requiredModules.length} Tauri modules.`,
);
